INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-03-10-netherlands-cabinet-leans-broad', '2026-03-10', '2026-03', 'The State Secretary for Finance formally submits the ViDA advisory report to Parliament, endorsing a Peppol-based domestic B2B mandate phased between 2030 and 2032 — though no legislation has yet been adopted.', '<h3>🇳🇱 Cabinet leans toward a domestic B2B e-invoicing mandate</h3>
<p>On 10 March 2026, the Dutch State Secretary of Finance formally submitted the January advisory report to the House of Representatives, alongside a ministerial letter setting out the government''s initial response. The signal is now directionally clear: the cabinet has taken the report''s ViDA-B recommendation into its political assessment, pointing specifically to the long-term reduction in administrative burden once the transition is complete.</p>
<p>The government has indicated interest in a broad domestic mandate — covering both intra-Community and domestic B2B transactions — built on the Peppol network, phased in from 2030 to 2032. This would put the Netherlands'' compliance regime firmly in the same camp as Belgium, France, Germany, Ireland, and Italy, each of which chose comprehensive domestic mandates over the EU''s bare cross-border minimum.</p>
<p>No legislation has been adopted, and the cabinet stopped short of a final decision — a formal government position was expected by summer 2026, with a public consultation on draft legislation planned for the fourth quarter of the year. For businesses trading in the Netherlands, this is the moment the country''s e-invoicing direction stopped being speculative and started being a matter of when and how, rather than if.</p>', 'https://www.rijksoverheid.nl', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-03-10-netherlands-cabinet-leans-broad', id FROM countries WHERE name_en = 'Netherlands';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-10-netherlands-cabinet-leans-broad', 'en', 'Cabinet leans toward a domestic B2B e-invoicing mandate', 'The State Secretary for Finance formally submits the ViDA advisory report to Parliament, endorsing a Peppol-based domestic B2B mandate phased between 2030 and 2032 — though no legislation has yet been adopted.', '<h3>🇳🇱 Cabinet leans toward a domestic B2B e-invoicing mandate</h3>
<p>On 10 March 2026, the Dutch State Secretary of Finance formally submitted the January advisory report to the House of Representatives, alongside a ministerial letter setting out the government''s initial response. The signal is now directionally clear: the cabinet has taken the report''s ViDA-B recommendation into its political assessment, pointing specifically to the long-term reduction in administrative burden once the transition is complete.</p>
<p>The government has indicated interest in a broad domestic mandate — covering both intra-Community and domestic B2B transactions — built on the Peppol network, phased in from 2030 to 2032. This would put the Netherlands'' compliance regime firmly in the same camp as Belgium, France, Germany, Ireland, and Italy, each of which chose comprehensive domestic mandates over the EU''s bare cross-border minimum.</p>
<p>No legislation has been adopted, and the cabinet stopped short of a final decision — a formal government position was expected by summer 2026, with a public consultation on draft legislation planned for the fourth quarter of the year. For businesses trading in the Netherlands, this is the moment the country''s e-invoicing direction stopped being speculative and started being a matter of when and how, rather than if.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-10-netherlands-cabinet-leans-broad', 'es', 'El gabinete se inclina hacia un mandato nacional de facturación electrónica B2B', 'El Secretario de Estado de Hacienda presenta formalmente al Parlamento el informe consultivo de ViDA, respaldando un mandato B2B nacional basado en Peppol y escalonado entre 2030 y 2032 — aunque aún no se ha adoptado ninguna legislación.', '<h3>🇳🇱 El gabinete se inclina hacia un mandato nacional de facturación electrónica B2B</h3>
<p>El 10 de marzo de 2026, el Secretario de Estado de Hacienda neerlandés presentó formalmente a la Cámara de Representantes el informe consultivo de enero, junto con una carta ministerial que expone la respuesta inicial del gobierno. La señal es ya direccionalmente clara: el gabinete ha incorporado la recomendación ViDA-B del informe a su valoración política, señalando específicamente la reducción a largo plazo de la carga administrativa una vez completada la transición.</p>
<p>El gobierno ha manifestado interés en un mandato nacional amplio — que cubra tanto las transacciones B2B intracomunitarias como las nacionales — construido sobre la red Peppol, escalonado entre 2030 y 2032. Esto situaría el régimen de cumplimiento de los Países Bajos firmemente en el mismo grupo que Bélgica, Francia, Alemania, Irlanda e Italia, que optaron por mandatos nacionales integrales en lugar del mínimo transfronterizo de la UE.</p>
<p>No se ha adoptado ninguna legislación, y el gabinete se detuvo antes de una decisión final — se esperaba una postura formal del gobierno para el verano de 2026, con una consulta pública sobre el anteproyecto de ley prevista para el cuarto trimestre del año. Para las empresas que operan en los Países Bajos, este es el momento en que la dirección de la facturación electrónica del país dejó de ser especulativa y pasó a ser una cuestión de cuándo y cómo, más que de si ocurrirá.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-10-netherlands-cabinet-leans-broad', 'de', 'Kabinett tendiert zu einer inländischen B2B-E-Rechnungspflicht', 'Der Staatssekretär für Finanzen übermittelt dem Parlament formell das ViDA-Gutachten und befürwortet eine Peppol-basierte inländische B2B-Pflicht, gestaffelt zwischen 2030 und 2032 — es wurde jedoch noch keine Gesetzgebung verabschiedet.', '<h3>🇳🇱 Kabinett tendiert zu einer inländischen B2B-E-Rechnungspflicht</h3>
<p>Am 10. März 2026 übermittelte der niederländische Staatssekretär für Finanzen der Zweiten Kammer formell das Gutachten vom Januar, zusammen mit einem Ministerschreiben, das die erste Reaktion der Regierung darlegt. Das Signal ist nun richtungsweisend klar: Das Kabinett hat die ViDA-B-Empfehlung des Gutachtens in seine politische Bewertung aufgenommen und verweist insbesondere auf die langfristige Verringerung des Verwaltungsaufwands nach Abschluss des Übergangs.</p>
<p>Die Regierung hat Interesse an einer breiten inländischen Pflicht signalisiert — die sowohl innergemeinschaftliche als auch inländische B2B-Umsätze abdeckt —, aufgebaut auf dem Peppol-Netzwerk, gestaffelt von 2030 bis 2032. Damit würde sich das niederländische Compliance-Regime fest in dieselbe Gruppe wie Belgien, Frankreich, Deutschland, Irland und Italien einreihen, die sich alle für umfassende inländische Pflichten statt des bloßen grenzüberschreitenden EU-Minimums entschieden haben.</p>
<p>Es wurde noch keine Gesetzgebung verabschiedet, und das Kabinett blieb vor einer endgültigen Entscheidung stehen — eine formelle Regierungsposition wurde für den Sommer 2026 erwartet, mit einer öffentlichen Konsultation zum Gesetzentwurf, die für das vierte Quartal des Jahres geplant war. Für Unternehmen, die in den Niederlanden tätig sind, ist dies der Moment, in dem die Richtung der niederländischen E-Rechnung aufhörte, spekulativ zu sein, und zu einer Frage des Wann und Wie wurde, statt des Ob.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-10-netherlands-cabinet-leans-broad', 'fr', 'Le cabinet penche vers une obligation nationale de facturation électronique B2B', 'Le secrétaire d''État aux Finances transmet formellement au Parlement le rapport consultatif ViDA, appuyant une obligation B2B nationale basée sur Peppol et échelonnée entre 2030 et 2032 — bien qu''aucune législation n''ait encore été adoptée.', '<h3>🇳🇱 Le cabinet penche vers une obligation nationale de facturation électronique B2B</h3>
<p>Le 10 mars 2026, le secrétaire d''État néerlandais aux Finances a transmis formellement à la Chambre des représentants le rapport consultatif de janvier, accompagné d''une lettre ministérielle exposant la première réponse du gouvernement. Le signal est désormais clair sur la direction : le cabinet a intégré la recommandation ViDA-B du rapport dans son appréciation politique, soulignant en particulier la réduction à long terme de la charge administrative une fois la transition achevée.</p>
<p>Le gouvernement a signalé un intérêt pour une obligation nationale large — couvrant à la fois les transactions B2B intracommunautaires et nationales — construite sur le réseau Peppol, échelonnée de 2030 à 2032. Cela placerait le régime de conformité des Pays-Bas fermement dans le même camp que la Belgique, la France, l''Allemagne, l''Irlande et l''Italie, qui ont toutes opté pour des obligations nationales complètes plutôt que le simple minimum transfrontalier de l''UE.</p>
<p>Aucune législation n''a été adoptée, et le cabinet s''est arrêté avant une décision finale — une position gouvernementale formelle était attendue pour l''été 2026, avec une consultation publique sur le projet de loi prévue pour le quatrième trimestre de l''année. Pour les entreprises opérant aux Pays-Bas, c''est le moment où l''orientation du pays en matière de facturation électronique a cessé d''être spéculative pour devenir une question de quand et comment, plutôt que de si.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-07-09-netherlands-cabinet-nears-decision', '2026-07-09', '2026-07', 'The Netherlands is working toward a summer 2026 decision on domestic e-invoicing scope, with Belgium''s B2B mandate already in force and France''s phased rollout beginning in September.', '<h3>🇳🇱 Cabinet nears a final decision, as neighbouring mandates go live</h3>
<p>As of 9 July 2026, the Dutch cabinet is actively working toward the "this summer" decision it signalled back in March: whether the country''s coming e-invoicing regime will stay limited to the EU''s cross-border minimum (ViDA-A), or extend to nearly all domestic B2B invoicing (ViDA-B). State Secretary Eerenberg for Finance is weighing advisory firm EY''s March recommendation to go broad — which EY argues delivers higher upfront implementation costs but a substantial long-term reduction in administrative burden — against the political and practical case for staying minimal.</p>
<p>The decision lands at a moment when the Netherlands'' traditionally cautious, market-driven stance looks increasingly like an outlier. Belgium''s mandatory four-corner Peppol model for domestic B2B invoicing has been in force since 1 January 2026, with a five-corner e-reporting model planned for 2028. France begins its own phased mandate through certified Plateformes Agréées in September 2026. Germany, too, is already underway. Every EU country that has reached a decision so far has chosen to include domestic B2B transactions rather than confine itself to the cross-border floor.</p>
<p>No decision has yet been announced. Once it is, expect it to determine — for the first time with real specificity — whether virtually every VAT-registered business in the Netherlands will eventually need Peppol capability, or only those trading across EU borders.</p>', 'https://www.peppol.nu', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-07-09-netherlands-cabinet-nears-decision', id FROM countries WHERE name_en = 'Netherlands';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-09-netherlands-cabinet-nears-decision', 'en', 'Cabinet nears a final decision, as neighbouring mandates go live', 'The Netherlands is working toward a summer 2026 decision on domestic e-invoicing scope, with Belgium''s B2B mandate already in force and France''s phased rollout beginning in September.', '<h3>🇳🇱 Cabinet nears a final decision, as neighbouring mandates go live</h3>
<p>As of 9 July 2026, the Dutch cabinet is actively working toward the "this summer" decision it signalled back in March: whether the country''s coming e-invoicing regime will stay limited to the EU''s cross-border minimum (ViDA-A), or extend to nearly all domestic B2B invoicing (ViDA-B). State Secretary Eerenberg for Finance is weighing advisory firm EY''s March recommendation to go broad — which EY argues delivers higher upfront implementation costs but a substantial long-term reduction in administrative burden — against the political and practical case for staying minimal.</p>
<p>The decision lands at a moment when the Netherlands'' traditionally cautious, market-driven stance looks increasingly like an outlier. Belgium''s mandatory four-corner Peppol model for domestic B2B invoicing has been in force since 1 January 2026, with a five-corner e-reporting model planned for 2028. France begins its own phased mandate through certified Plateformes Agréées in September 2026. Germany, too, is already underway. Every EU country that has reached a decision so far has chosen to include domestic B2B transactions rather than confine itself to the cross-border floor.</p>
<p>No decision has yet been announced. Once it is, expect it to determine — for the first time with real specificity — whether virtually every VAT-registered business in the Netherlands will eventually need Peppol capability, or only those trading across EU borders.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-09-netherlands-cabinet-nears-decision', 'es', 'El gabinete se acerca a una decisión final, mientras los mandatos vecinos entran en vigor', 'Los Países Bajos trabajan hacia una decisión en el verano de 2026 sobre el alcance nacional de la facturación electrónica, mientras el mandato B2B de Bélgica ya está en vigor y el despliegue por fases de Francia comienza en septiembre.', '<h3>🇳🇱 El gabinete se acerca a una decisión final, mientras los mandatos vecinos entran en vigor</h3>
<p>A fecha de 9 de julio de 2026, el gabinete neerlandés trabaja activamente hacia la decisión "de este verano" que señaló en marzo: si el próximo régimen de facturación electrónica del país se limitará al mínimo transfronterizo de la UE (ViDA-A) o se ampliará a prácticamente toda la facturación B2B nacional (ViDA-B). El Secretario de Estado de Hacienda, Eerenberg, está sopesando la recomendación de marzo de la consultora EY de optar por el alcance amplio — que, según EY, conlleva mayores costes iniciales de implementación pero una reducción sustancial de la carga administrativa a largo plazo — frente al argumento político y práctico de mantenerse en el mínimo.</p>
<p>La decisión llega en un momento en que la postura tradicionalmente cautelosa e impulsada por el mercado de los Países Bajos parece cada vez más una excepción. El modelo Peppol de cuatro esquinas obligatorio de Bélgica para la facturación B2B nacional está en vigor desde el 1 de enero de 2026, con un modelo de reporte de cinco esquinas previsto para 2028. Francia inicia su propio mandato escalonado a través de Plateformes Agréées certificadas en septiembre de 2026. Alemania también está ya en marcha. Todos los países de la UE que han llegado a una decisión hasta ahora han optado por incluir las transacciones B2B nacionales en lugar de limitarse al suelo transfronterizo.</p>
<p>Aún no se ha anunciado ninguna decisión. Una vez que se anuncie, se espera que determine — por primera vez con especificidad real — si prácticamente todas las empresas neerlandesas registradas a efectos de IVA necesitarán finalmente capacidad Peppol, o solo las que comercian a través de fronteras de la UE.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-09-netherlands-cabinet-nears-decision', 'de', 'Kabinett nähert sich einer endgültigen Entscheidung, während Nachbarpflichten in Kraft treten', 'Die Niederlande arbeiten auf eine Entscheidung im Sommer 2026 über den Umfang der inländischen E-Rechnung hin, während Belgiens B2B-Pflicht bereits in Kraft ist und Frankreichs stufenweiser Rollout im September beginnt.', '<h3>🇳🇱 Kabinett nähert sich einer endgültigen Entscheidung, während Nachbarpflichten in Kraft treten</h3>
<p>Stand 9. Juli 2026 arbeitet das niederländische Kabinett aktiv auf die im März signalisierte Entscheidung "in diesem Sommer" hin: ob das kommende E-Rechnungs-Regime des Landes auf das grenzüberschreitende EU-Minimum (ViDA-A) beschränkt bleibt oder auf nahezu die gesamte inländische B2B-Rechnungsstellung ausgeweitet wird (ViDA-B). Staatssekretär Eerenberg für Finanzen wägt die Empfehlung des Beratungsunternehmens EY vom März, den breiten Weg zu gehen — was laut EY höhere anfängliche Umsetzungskosten, aber eine erhebliche langfristige Verringerung des Verwaltungsaufwands mit sich bringt — gegen das politische und praktische Argument ab, beim Minimum zu bleiben.</p>
<p>Die Entscheidung fällt in einem Moment, in dem die traditionell zurückhaltende, marktgetriebene Haltung der Niederlande zunehmend wie ein Ausreißer wirkt. Belgiens verpflichtendes Vier-Ecken-Peppol-Modell für die inländische B2B-Rechnungsstellung ist seit dem 1. Januar 2026 in Kraft, ein Fünf-Ecken-Meldemodell ist für 2028 geplant. Frankreich beginnt im September 2026 seine eigene stufenweise Pflicht über zertifizierte Plateformes Agréées. Auch Deutschland ist bereits unterwegs. Jedes EU-Land, das bislang eine Entscheidung getroffen hat, hat sich für die Einbeziehung inländischer B2B-Umsätze entschieden, statt sich auf die grenzüberschreitende Untergrenze zu beschränken.</p>
<p>Bislang wurde keine Entscheidung bekanntgegeben. Sobald sie vorliegt, dürfte sie erstmals mit echter Genauigkeit festlegen, ob praktisch jedes umsatzsteuerregistrierte Unternehmen in den Niederlanden letztlich Peppol-Fähigkeit benötigt oder nur die grenzüberschreitend innerhalb der EU Handelnden.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-09-netherlands-cabinet-nears-decision', 'fr', 'Le cabinet approche d''une décision finale, alors que les obligations voisines entrent en vigueur', 'Les Pays-Bas travaillent vers une décision à l''été 2026 sur le périmètre national de la facturation électronique, alors que l''obligation B2B belge est déjà en vigueur et que le déploiement échelonné français débute en septembre.', '<h3>🇳🇱 Le cabinet approche d''une décision finale, alors que les obligations voisines entrent en vigueur</h3>
<p>Au 9 juillet 2026, le cabinet néerlandais travaille activement vers la décision « de cet été » qu''il avait signalée en mars : le futur régime de facturation électronique du pays restera-t-il limité au minimum transfrontalier de l''UE (ViDA-A), ou s''étendra-t-il à la quasi-totalité de la facturation B2B nationale (ViDA-B) ? Le secrétaire d''État aux Finances Eerenberg pèse la recommandation de mars du cabinet de conseil EY d''opter pour le périmètre large — ce qui, selon EY, entraîne des coûts de mise en œuvre initiaux plus élevés mais une réduction substantielle de la charge administrative à long terme — face à l''argument politique et pratique de rester au minimum.</p>
<p>La décision intervient à un moment où la posture traditionnellement prudente et guidée par le marché des Pays-Bas apparaît de plus en plus comme une exception. Le modèle Peppol à quatre coins obligatoire de la Belgique pour la facturation B2B nationale est en vigueur depuis le 1er janvier 2026, avec un modèle de déclaration à cinq coins prévu pour 2028. La France entame sa propre obligation échelonnée via des Plateformes Agréées certifiées en septembre 2026. L''Allemagne est également déjà en marche. Chaque pays de l''UE ayant tranché jusqu''à présent a choisi d''inclure les transactions B2B nationales plutôt que de se limiter au plancher transfrontalier.</p>
<p>Aucune décision n''a encore été annoncée. Une fois rendue, elle devrait déterminer — pour la première fois avec une réelle précision — si pratiquement toutes les entreprises néerlandaises assujetties à la TVA auront besoin de la capacité Peppol, ou seulement celles opérant à travers les frontières de l''UE.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2025-10-20-netherlands-why-no-b2b-mandate-yet', '2025-10-20', '2025-10', 'A backgrounder on the Netherlands'' deliberately market-driven approach: no clearance, no domestic mandate, but unusually high voluntary Peppol adoption driven by procurement pressure rather than law.', '<h3>🇳🇱 Why the Netherlands hasn''t mandated B2B e-invoicing (yet)</h3>
<p>Most of the countries in this tracker got to structured e-invoicing through a mandate — a law with a date attached. The Netherlands is the tracker''s clearest counter-example: B2G e-invoicing has been mandatory since 2017 (central government) and 2019 (all public bodies), but B2B remains entirely voluntary today, with no domestic clearance model and no real-time reporting regime of any kind.</p>
<p>What makes the Dutch case interesting isn''t the absence of a mandate — plenty of countries lack one — but how high voluntary adoption has climbed anyway. Most mainstream Dutch ERP and accounting software supports Peppol BIS 3.0 / SI-UBL 2.0 natively, largely because the same standard already underpins B2G traffic. And increasingly, adoption is being driven not by government pressure but by commercial pressure: major counterparties are making Peppol capability a de facto procurement condition, so businesses without it risk losing deals rather than facing fines.</p>
<p>That quiet, market-driven success is precisely what makes the Netherlands'' current policy decision consequential. A government-commissioned report has recommended converting today''s voluntary norm into tomorrow''s legal requirement — arguing that formalising what the market has already mostly achieved would still meaningfully reduce fraud and administrative burden. Whether the cabinet agrees is the open question the rest of this country''s coverage is tracking.</p>', 'https://www.logius.nl', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2025-10-20-netherlands-why-no-b2b-mandate-yet', id FROM countries WHERE name_en = 'Netherlands';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-10-20-netherlands-why-no-b2b-mandate-yet', 'en', 'Why the Netherlands hasn''t mandated B2B e-invoicing (yet)', 'A backgrounder on the Netherlands'' deliberately market-driven approach: no clearance, no domestic mandate, but unusually high voluntary Peppol adoption driven by procurement pressure rather than law.', '<h3>🇳🇱 Why the Netherlands hasn''t mandated B2B e-invoicing (yet)</h3>
<p>Most of the countries in this tracker got to structured e-invoicing through a mandate — a law with a date attached. The Netherlands is the tracker''s clearest counter-example: B2G e-invoicing has been mandatory since 2017 (central government) and 2019 (all public bodies), but B2B remains entirely voluntary today, with no domestic clearance model and no real-time reporting regime of any kind.</p>
<p>What makes the Dutch case interesting isn''t the absence of a mandate — plenty of countries lack one — but how high voluntary adoption has climbed anyway. Most mainstream Dutch ERP and accounting software supports Peppol BIS 3.0 / SI-UBL 2.0 natively, largely because the same standard already underpins B2G traffic. And increasingly, adoption is being driven not by government pressure but by commercial pressure: major counterparties are making Peppol capability a de facto procurement condition, so businesses without it risk losing deals rather than facing fines.</p>
<p>That quiet, market-driven success is precisely what makes the Netherlands'' current policy decision consequential. A government-commissioned report has recommended converting today''s voluntary norm into tomorrow''s legal requirement — arguing that formalising what the market has already mostly achieved would still meaningfully reduce fraud and administrative burden. Whether the cabinet agrees is the open question the rest of this country''s coverage is tracking.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-10-20-netherlands-why-no-b2b-mandate-yet', 'es', 'Por qué los Países Bajos aún no han impuesto un mandato de facturación electrónica B2B', 'Un artículo de contexto sobre el enfoque deliberadamente impulsado por el mercado de los Países Bajos: sin compensación, sin mandato nacional, pero con una adopción voluntaria de Peppol inusualmente alta impulsada por la presión de la contratación más que por la ley.', '<h3>🇳🇱 Por qué los Países Bajos aún no han impuesto un mandato de facturación electrónica B2B</h3>
<p>La mayoría de los países de este rastreador llegaron a la facturación electrónica estructurada a través de un mandato — una ley con una fecha asociada. Los Países Bajos son el contraejemplo más claro del rastreador: la facturación electrónica B2G es obligatoria desde 2017 (gobierno central) y 2019 (todos los organismos públicos), pero el B2B sigue siendo hoy totalmente voluntario, sin modelo nacional de compensación y sin ningún régimen de reporte en tiempo real.</p>
<p>Lo interesante del caso neerlandés no es la ausencia de un mandato — muchos países carecen de uno —, sino lo alto que ha llegado a ser, aun así, la adopción voluntaria. La mayoría del software neerlandés habitual de ERP y contabilidad admite de forma nativa Peppol BIS 3.0 / SI-UBL 2.0, en gran parte porque el mismo estándar ya sustenta el tráfico B2G. Y, cada vez más, la adopción no la impulsa la presión gubernamental sino la presión comercial: las grandes contrapartes están convirtiendo la capacidad Peppol en una condición de contratación de facto, de modo que las empresas que carecen de ella arriesgan perder negocio en lugar de enfrentarse a multas.</p>
<p>Ese silencioso éxito impulsado por el mercado es precisamente lo que hace consecuente la decisión política actual de los Países Bajos. Un informe encargado por el gobierno ha recomendado convertir la norma voluntaria de hoy en el requisito legal de mañana — argumentando que formalizar lo que el mercado ya ha logrado en gran medida seguiría reduciendo de forma significativa el fraude y la carga administrativa. Si el gabinete está de acuerdo es la pregunta abierta que sigue el resto de la cobertura de este país.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-10-20-netherlands-why-no-b2b-mandate-yet', 'de', 'Warum die Niederlande B2B-E-Rechnung (noch) nicht verpflichtend gemacht haben', 'Ein Hintergrundbericht über den bewusst marktgetriebenen Ansatz der Niederlande: keine Clearance, keine inländische Pflicht, aber eine ungewöhnlich hohe freiwillige Peppol-Verbreitung, getrieben von Beschaffungsdruck statt von Gesetzen.', '<h3>🇳🇱 Warum die Niederlande B2B-E-Rechnung (noch) nicht verpflichtend gemacht haben</h3>
<p>Die meisten Länder in diesem Tracker kamen über eine Pflicht zur strukturierten E-Rechnung — ein Gesetz mit einem Datum. Die Niederlande sind das klarste Gegenbeispiel im Tracker: B2G-E-Rechnung ist seit 2017 (Zentralregierung) und 2019 (alle öffentlichen Stellen) verpflichtend, B2B bleibt heute jedoch vollständig freiwillig, ohne inländisches Clearance-Modell und ohne jegliches Echtzeit-Meldesystem.</p>
<p>Was den niederländischen Fall interessant macht, ist nicht das Fehlen einer Pflicht — viele Länder haben keine —, sondern wie hoch die freiwillige Verbreitung dennoch gestiegen ist. Die meiste gängige niederländische ERP- und Buchhaltungssoftware unterstützt Peppol BIS 3.0 / SI-UBL 2.0 nativ, größtenteils weil derselbe Standard bereits dem B2G-Verkehr zugrunde liegt. Und zunehmend wird die Verbreitung nicht durch staatlichen Druck, sondern durch kommerziellen Druck vorangetrieben: Wichtige Geschäftspartner machen Peppol-Fähigkeit zu einer De-facto-Beschaffungsbedingung, sodass Unternehmen ohne diese Fähigkeit eher Geschäfte verlieren als Strafen riskieren.</p>
<p>Genau dieser stille, marktgetriebene Erfolg macht die aktuelle politische Entscheidung der Niederlande bedeutsam. Ein von der Regierung in Auftrag gegebenes Gutachten hat empfohlen, die heutige freiwillige Norm in die gesetzliche Pflicht von morgen zu überführen — mit dem Argument, dass die Formalisierung dessen, was der Markt bereits größtenteils erreicht hat, Betrug und Verwaltungsaufwand weiterhin spürbar verringern würde. Ob das Kabinett zustimmt, ist die offene Frage, der der Rest der Berichterstattung zu diesem Land nachgeht.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-10-20-netherlands-why-no-b2b-mandate-yet', 'fr', 'Pourquoi les Pays-Bas n''ont pas (encore) rendu obligatoire la facturation électronique B2B', 'Un article de contexte sur l''approche délibérément guidée par le marché des Pays-Bas : pas de validation préalable, pas d''obligation nationale, mais une adoption volontaire de Peppol inhabituellement élevée, portée par la pression des achats plutôt que par la loi.', '<h3>🇳🇱 Pourquoi les Pays-Bas n''ont pas (encore) rendu obligatoire la facturation électronique B2B</h3>
<p>La plupart des pays de ce tracker sont parvenus à la facturation électronique structurée par une obligation — une loi assortie d''une date. Les Pays-Bas constituent le contre-exemple le plus clair du tracker : la facturation électronique B2G est obligatoire depuis 2017 (administration centrale) et 2019 (tous les organismes publics), mais le B2B reste aujourd''hui entièrement volontaire, sans modèle national de validation préalable et sans aucun régime de déclaration en temps réel.</p>
<p>Ce qui rend le cas néerlandais intéressant n''est pas l''absence d''obligation — de nombreux pays n''en ont pas —, mais le niveau auquel l''adoption volontaire est néanmoins montée. La plupart des logiciels ERP et comptables néerlandais courants prennent nativement en charge Peppol BIS 3.0 / SI-UBL 2.0, en grande partie parce que la même norme sous-tend déjà le trafic B2G. Et de plus en plus, l''adoption est portée non par la pression gouvernementale mais par la pression commerciale : les grandes contreparties font de la capacité Peppol une condition d''achat de facto, si bien que les entreprises qui en sont dépourvues risquent de perdre des affaires plutôt que de s''exposer à des amendes.</p>
<p>Ce succès discret, guidé par le marché, est précisément ce qui rend consequente la décision politique actuelle des Pays-Bas. Un rapport commandé par le gouvernement a recommandé de transformer la norme volontaire d''aujourd''hui en obligation légale de demain — en avançant que formaliser ce que le marché a déjà largement accompli réduirait encore sensiblement la fraude et la charge administrative. Savoir si le cabinet est d''accord est la question ouverte que suit le reste de la couverture de ce pays.</p>');

